            $this->patterns,
            $this->patternsForEveryOccurrence,
            $this->lexemes,
            $this->lexicalTarget,
            $this->parameters,
            true,
            $this->maxDepth,
            $this->reserveSteps,
            $this->expansionBudget,
            $this->candidateKeys,
        );
    }

    /**
