            $this->startRule,
            $this->patterns,
            $this->patternsForEveryOccurrence,
            $lexemes,
            $this->lexicalTarget,
            $this->parameters,
            $this->requiresNonEmpty,
            $this->maxDepth,
            $this->reserveSteps,
            $this->expansionBudget,
            $this->candidateKeys,
        );
    }

    /**
     * Answers a plan whose walk recurses no deeper than the caller allows.
     * @return self<TRequiresNonEmpty> Plan bounded to that depth
     */
    public function withMaxDepth(int $maxDepth): self
    {
        return new self(
            $this->startRule,
            $this->patterns,
            $this->patternsForEveryOccurrence,
            $this->lexemes,
            $this->lexicalTarget,
            $this->parameters,
            $this->requiresNonEmpty,
            max(1, $maxDepth),
            $this->reserveSteps,
            $this->expansionBudget,
            $this->candidateKeys,
        );
    }

    /**
