                $character = $value[$offset++];
            }
            if (!str_contains('0123456789', $character)) {
                break;
            }
            $digits .= $character;
            $magnitude = ltrim($digits, '0');
            $magnitude = $magnitude === '' ? '0' : $magnitude;
