declare(strict_types=1);

namespace SqlFaker\Grammar\Model;

use InvalidArgumentException;
use RuntimeException;

/**
 * Represents a formal grammar for SQL generation.
 *
 * A formal grammar G = (N, Sigma, P, S) where:
 * - N: Set of non-terminal symbols (keys of ruleMap)
 * - Sigma: Set of terminal symbols (implicitly defined by Symbol types)
 * - P: Set of production rules (ruleMap)
 * - S: Start symbol (startSymbol)
 *
 * @visibility root
 */
final class Grammar
{
    /**
     * @param string $startSymbol The grammar's start symbol
     * @param array<string, ProductionRule> $ruleMap Non-terminal name => ProductionRule
     *
     * @param array<string, string> $aliases Specialized rule => original grammar rule
     * @throws InvalidArgumentException When a rule is filed under a name other than its own left-hand side
     */
    public function __construct(
        public readonly string $startSymbol,
        public readonly array $ruleMap,
        public readonly array $aliases = [],
    ) {
        foreach ($ruleMap as $key => $rule) {
            if ($key !== $rule->lhs) {
                throw new InvalidArgumentException(
                    "Rule key '{$key}' does not match rule lhs '{$rule->lhs}'"
                );
            }
        }
    }

    /**
     * Reads both historical grammar resources and newly specialized grammars.
     * @param array{startSymbol: string, ruleMap: array<string, ProductionRule>, aliases?: array<string, string>} $data
     */
    public function __unserialize(array $data): void
    {
        $this->startSymbol = $data['startSymbol'];
        $this->ruleMap = $data['ruleMap'];
        $this->aliases = $data['aliases'] ?? [];
    }

    /**
     * Names the source rule behind a specialized subtree.
     */
    public function sourceRule(string $rule): string
    {
        return $this->aliases[$rule] ?? $rule;
    }

    /**
     * Recovers the alternative index used before plan specialization.
     */
    public function sourceOrdinal(string $rule, int $ordinal): int
    {
        return isset($this->aliases[$rule]) ? ($this->ruleMap[$rule]->alternatives[$ordinal]->ordinal ?? $ordinal) : $ordinal;
    }

    /**
     * Load a pre-compiled grammar from a file path.
     *
     * @throws RuntimeException When the compiled grammar is missing, empty, or is not a grammar
     */
    public static function loadFromFile(string $path): self
    {
        if (!file_exists($path)) {
            throw new RuntimeException("Grammar file not found: {$path}");
        }

        /** @var array<string, string> $data */
        $data = require $path;
        $hash = array_key_first($data);
        if ($hash === null) {
            throw new RuntimeException("Invalid grammar file: {$path}");
        }
        $grammar = unserialize($data[$hash]);

        if (!$grammar instanceof self) {
            throw new RuntimeException("Failed to load grammar from: {$path}");
        }

        return $grammar->identified();
    }
    /**
     * Assigns original ordinals before any dialect adapter filters alternatives.
     */
    public function identified(): self
    {
        $rules = [];
        foreach ($this->ruleMap as $name => $rule) {
            $alternatives = [];
            foreach ($rule->alternatives as $ordinal => $production) {
                $alternatives[] = new Production(
                    $production->symbols,
                    $production->ordinal ?? $ordinal,
                    $production->origin ?? $name . '#' . $ordinal
                );
            }
            $rules[$name] = new ProductionRule($name, $alternatives);
        }
        return new self($this->startSymbol, $rules, $this->aliases);
    }
}

