<?php

declare(strict_types=1);

namespace SqlFaker\Generation\Exception;

use RuntimeException;

/**
 * Reports that a grammar could not derive a statement.
 *
 * A rule with no alternatives, an alternative no lexer can realize, a reference
 * to a rule the grammar does not define, or a derivation that runs past its
 * depth limit are all properties of the grammar being generated from, not of
 * the generator. Callers that generate from grammars they did not author are
 * expected to handle this.
 *
 * The three dialect generators hit the same failures, so the wording lives here
 * rather than being repeated at each throw site.
 *
 * @visibility public
 * @example Catch this failure as a runtime exception
 *     $failure = new \SqlFaker\Generation\Exception\GenerationException('SQL generation failed');
 *     $failure instanceof \RuntimeException // => true
 *     $failure->getMessage() // => 'SQL generation failed'
 */
final class GenerationException extends RuntimeException
{
    /**
     * Reports a derivation that ran past the plan's depth budget.
     *
     * @return self Exception describing the exhausted budget
     * @visibility root
     */
    public static function derivationLimitExceeded(): self
    {
        return new self('Exceeded derivation limit while generating SQL.');
    }

    /**
     * Reports a reference to a rule the grammar does not define.
     *
     * @param string $rule Name the production referred to
     *
     * @return self Exception naming the missing rule
     * @visibility root
     */
    public static function unknownRule(string $rule): self
    {
        return new self("Unknown grammar rule: {$rule}");
    }

    /**
     * Reports a rule that declares no alternatives to choose from.
     *
     * @param string $rule Name of the empty rule
     *
     * @return self Exception naming the empty rule
     * @visibility root
     */
    public static function ruleHasNoAlternatives(string $rule): self
    {
        return new self("Production rule '{$rule}' has no alternatives.");
    }

    /**
     * Reports a rule whose alternatives cannot all be turned into tokens.
     *
     * @param string $rule Name of the unrealizable rule
     *
     * @return self Exception naming the unrealizable rule
     * @visibility root
     */
    public static function noRealizableAlternative(string $rule): self
    {
        return new self("Grammar rule has no lexically realizable alternative: {$rule}");
    }

    /**
     * Reports a rule with no alternative the generation plan admits.
     *
     * @param string $rule Name of the constrained rule
     *
     * @return self Exception naming the constrained rule
     * @visibility root
     */
    public static function noAlternativeMatchingPlan(string $rule): self
    {
        return new self("Grammar rule has no alternative matching the generation plan: {$rule}");
    }

    /**
     * Reports a start rule that cannot satisfy the plan's non-empty requirement.
     *
     * @param string $rule Name of the start rule
     *
     * @return self Exception naming the start rule
     * @visibility root
     */
    public static function startRuleCannotProduceOutput(string $rule): self
    {
        return new self(
            "Generation plan requires non-empty output, but the start rule cannot produce it: {$rule}",
        );
    }

    /**
     * Reports a plan that demanded output the grammar only produced as empty.
     *
     * @param string $dialect Dialect the generator was producing for
     *
     * @return self Exception naming the dialect
     * @visibility root
     */
    public static function planRequiresNonEmptyOutput(string $dialect): self
    {
        return new self("{$dialect} generation plan requires non-empty output.");
    }

    /**
     * Reports that every derivation attempt failed to reach concrete SQL.
     *
     * @param string $dialect Dialect the generator was producing for
     *
     * @return self Exception naming the dialect
     * @visibility root
     */
    public static function lexicalRealizationFailed(string $dialect): self
    {
        return new self("{$dialect} lexical realization failed.");
    }
}
<?php

declare(strict_types=1);

namespace SqlFaker\Generation\Exception;

use RuntimeException;
use SqlFaker\Grammar\Model\Terminal;

/**
 * Reports missing lexical definitions, incompatible candidates and diagnostic tokenizer failures.
 *
 * Generation checks source-derived lexical and spacing conditions before serialization.
 * Tokenizer diagnostics remain available separately; token equality is not the acceptance oracle.
 *
 * @visibility public
 * @example Catch this failure as a runtime exception
 *     $failure = new \SqlFaker\Generation\Exception\LexicalException('SQL generation failed');
 *     $failure instanceof \RuntimeException // => true
 *     $failure->getMessage() // => 'SQL generation failed'
 */
final class LexicalException extends RuntimeException
{
    /**
     * Reports a terminal without an applicable lexical generator.
     *
     * @param string $dialect Dialect label supplied by the calling implementation
     * @param string $version Lexical profile version in use
     * @param string $terminal Terminal that was asked for
     *
     * @return self Exception naming the terminal and the profile
     * @visibility root
     */
    public static function unsupportedTerminal(string $dialect, string $version, string $terminal): self
    {
        return new self("Unsupported {$dialect} terminal for {$version}: {$terminal}");
    }

    /**
     * Reports SQL text the tokenizer cannot read at all.
     *
     * @param string $dialect Dialect name as it appears in messages
     * @param int $offset Where the tokenizer stopped
     * @param string $sql The text being read
     *
     * @return self Exception naming the offset and the text
     * @visibility root
     */
    public static function unsupportedInput(string $dialect, int $offset, string $sql): self
    {
        return new self("Unsupported {$dialect} lexical input at offset {$offset}: {$sql}");
    }

    /**
     * Reports a read that did not get past where it started.
     *
     * A scanner that stays where it is has not read anything, and the loop
     * around it would run forever. Saying so at the point it happens turns a
     * hang into a failure that names the offset it happened at.
     *
     * @param string $dialect Dialect name as it appears in messages
     * @param int $offset Offset the read started and ended at
     * @param string $sql The text being read
     *
     * @return self Exception naming the offset and the text
     * @visibility root
     */
    public static function noProgress(string $dialect, int $offset, string $sql): self
    {
        return new self("{$dialect} lexer made no progress at offset {$offset}: {$sql}");
    }

    /**
     * Reports a quoted run that never closes.
     *
     * @param string $dialect Dialect name as it appears in messages
     * @param string $sql The text being read
     *
     * @return self Exception naming the text
     * @visibility root
     */
    public static function unterminatedQuotedToken(string $dialect, string $sql): self
    {
        return new self("Unterminated {$dialect} quoted token: {$sql}");
    }

    /**
     * Reports a bracketed identifier that never closes.
     *
     * @param string $dialect Dialect name as it appears in messages
     *
     * @return self Exception describing the truncation
     * @visibility root
     */
    public static function unterminatedBracketIdentifier(string $dialect): self
    {
        return new self("Unterminated {$dialect} bracket identifier.");
    }

    /**
     * Reports a block comment that never closes.
     *
     *…686 tokens truncated…   string $version,
        array $expected,
        array $actual,
        string $sql,
    ): self {
        return new self(sprintf(
            "%s lexical round-trip failed for %s.\nExpected: %s\nActual: %s\nSQL: %s",
            $dialect,
            $version,
            self::rendered($expected),
            self::rendered($actual),
            $sql,
        ));
    }

    /**
     * Renders a token sequence for a failure message.
     *
     * The sequences being compared came out of arbitrary generated bytes, so
     * rendering them can meet input JSON has no encoding for. Substituting
     * those bytes keeps the round-trip failure reportable: a message that could
     * itself fail would hide the thing worth reporting behind an encoding
     * error.
     *
     * @param list<string> $tokens Tokens to render
     *
     * @return string The sequence as JSON, or a placeholder when it cannot be rendered
     * @visibility root
     */
    public static function rendered(array $tokens): string
    {
        $json = json_encode($tokens, JSON_INVALID_UTF8_SUBSTITUTE);

        return is_string($json) ? $json : '(unrenderable)';
    }
}
