add('Generation/Plan/RulePlanTest.php',r'''
    public function testAnyLeavesEveryKindOfChoiceUnspecified(): void
    {
        $plan = RulePlan::any();
        self::assertNull($plan->pattern);
        self::assertNull($plan->items);
        self::assertSame([], $plan->rules);
        self::assertSame([], $plan->children);
        self::assertSame([], $plan->lexemes);
    }

    public function testWithChildIntersectsOnlyTheSelectedOperand(): void
    {
        $plan = RulePlan::any()->withChild('expr', 1, RulePlan::any()->allowing(ProductionPattern::containing('ID')))
            ->withChild('expr', 1, RulePlan::any()->allowing(ProductionPattern::excluding(ProductionPattern::containing('DOT'))));
        self::assertArrayNotHasKey(0, $plan->children['expr']);
        self::assertTrue($plan->children['expr'][1]->pattern?->matches(['ID']));
        self::assertFalse($plan->children['expr'][1]->pattern->matches(['ID', 'DOT', 'ID']));
    }

    public function testWithLexemeIntersectsDomainsWithoutChangingOtherTokens(): void
    {
        $original = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('users', 'orders'))
            ->withLexeme('STRING', LexemeConstraint::oneOf("'Alice'"));
        $refined = $original->withLexeme('ID', LexemeConstraint::oneOf('users'));
        self::assertFalse($refined->lexemes['ID']->accepts('orders'));
        self::assertTrue($original->lexemes['ID']->accepts('orders'));
        self::assertSame($original->lexemes['STRING'], $refined->lexemes['STRING']);
    }

    public function testWithItemsRetainsHeterogeneousOutputOrder(): void
    {
        $name = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('name'));
        $score = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('score'));
        self::assertSame([$name, $score], RulePlan::any()->withItems($name, $score)->items);
    }

    public function testMergeIntersectsCorrespondingListItems(): void
    {
        $names = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('name', 'score'));
        $name = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('name'));
        $score = RulePlan::any()->withLexeme('ID', LexemeConstraint::oneOf('score'));
        $merged = RulePlan::any()->withItems($names, $names)->merge(RulePlan::any()->withItems($name, $score));
        self::assertTrue($merged->items[0]->lexemes['ID']->accepts('name'));
        self::assertFalse($merged->items[0]->lexemes['ID']->accepts('score'));
        self::assertTrue($merged->items[1]->lexemes['ID']->accepts('score'));
    }
''')
add('Generation/Plan/LexemeConstraintTest.php',r'''
    public function testChooseRetainsTheWholeIntegerIntervalIncludingItsBounds(): void
    {
        $range = LexemeConstraint::integers(0, PHP_INT_MAX);
        self::assertSame('0', $range->choose(static fn (int $count): int => 0));
        self::assertSame((string) PHP_INT_MAX, $range->choose(static fn (int $count): int => $count - 1));
    }

    public function testAcceptsUsesLexicalSpellingsRatherThanNumericCoercion(): void
    {
        $range = LexemeConstraint::integers(10, 20);
        self::assertTrue($range->accepts('10'));
        self::assertTrue($range->accepts('20'));
        foreach (['9', '21', '-10', '+10', "'10'", '1e1', '10.0', ' 10'] as $value) {
            self::assertFalse($range->accepts($value));
        }
    }

    public function testIntersectIsIndependentOfWhichSideHoldsTheFiniteSet(): void
    {
        $range = LexemeConstraint::integers(10, 20);
        $set = LexemeConstraint::oneOf('9', '10', '15', '21');
        self::assertEquals($range->intersect($set), $set->intersect($range));
        self::assertFalse($range->intersect($set)->accepts('11'));
        self::assertTrue($range->intersect($set)->accepts('15'));
    }
''')
add('Generation/Plan/ProductionPatternTest.php',r'''
    public function testAnyOfAcceptsEitherFormWithoutAcceptingUnrelatedForms(): void
    {
        $pattern = ProductionPattern::anyOf(ProductionPattern::containing('VALUES'), ProductionPattern::containing('SELECT'));
        self::assertTrue($pattern->matches(['VALUES', 'row']));
        self::assertTrue($pattern->matches(['SELECT', 'expr']));
        self::assertFalse($pattern->matches(['UPDATE', 'table']));
    }

    public function testExcludingCanExcludeAnOrdinalOrAnEmptyAlternative(): void
    {
        $pattern = ProductionPattern::excluding(ProductionPattern::at(1));
        self::assertTrue($pattern->matches(['ID'], 0));
        self::assertFalse($pattern->matches(['ID'], 1));
        self::assertFalse(ProductionPattern::excluding(ProductionPattern::exactly())->matches([]));
    }
''')
add('Generation/Plan/GenerationPlanTest.php',r'''
    public function testRulesExposeMergedConditionsWithoutMutatingTheOriginal(): void
    {
        $original = GenerationPlan::all()->withRule('stmt', \SqlFaker\Generation\Plan\RulePlan::any()->allowing(ProductionPattern::containing('SELECT')));
        $refined = $original->withRule('stmt', \SqlFaker\Generation\Plan\RulePlan::any()->allowing(ProductionPattern::excluding(ProductionPattern::containing('WITH'))));
        self::assertTrue($original->rules()['stmt']->pattern?->matches(['WITH', 'SELECT']));
        self::assertFalse($refined->rules()['stmt']->pattern?->matches(['WITH', 'SELECT']));
        self::assertTrue($refined->rules()['stmt']->pattern->matches(['SELECT']));
    }
''')
add('Generation/Plan/Compilation/ScopedGenerationTest.php',r'''
    public function testConstraintResolvesNearestAncestorWithoutAffectingOtherTokens(): void
    {
        $outer = LexemeConstraint::oneOf('outer');
        $inner = LexemeConstraint::oneOf('inner');
        $scope = new ScopedGeneration(new TerminalSequence([]), [0 => ['ID' => $outer], 10 => ['ID' => $inner]]);
        self::assertSame($inner, $scope->constraint(new TerminalOccurrence('ID', 1, [0, 10, 20])));
        self::assertSame($outer, $scope->constraint(new TerminalOccurrence('ID', 2, [0, 30])));
        self::assertNull($scope->constraint(new TerminalOccurrence('STRING', 3, [0, 10])));
    }

    public function testLexicalPlanPreservesLegacySpellingsWhenARewriterRenamesTokens(): void
    {
        $sequence = new TerminalSequence([new TerminalOccurrence('RENAMED', 1, [0])], original: [new TerminalOccurrence('ID', 1, [0])]);
        $scope = new ScopedGeneration($sequence, [0 => ['RENAMED' => LexemeConstraint::oneOf('users', 'orders')]]);
        $plan = $scope->lexicalPlan($sequence, GenerationPlan::all()->withLexemes(['ID' => ['orders']]), static fn (int $count): int => 0);
        self::assertSame('orders', $plan->lexemeAt('RENAMED', 0));
    }
''')
add('Generation/Plan/Compilation/GrammarCompilerTest.php',r'''
    public function testValidateAcceptsNestedChildAndListDeclarations(): void
    {
        $grammar = new Grammar('root', ['root' => new ProductionRule('root', [new Production([new Terminal('T')])])]);
        $compiler = new GrammarCompiler($grammar);
        $compiler->validate(['root' => RulePlan::any()->withChild('root', 0, RulePlan::any())->withItems(RulePlan::any()->withRule('root', RulePlan::any()))]);
        self::assertSame($grammar->ruleMap, $compiler->compile('root', [])->grammar->ruleMap === [] ? [] : $grammar->ruleMap);
    }

    public function testRuleMemoizesRecursiveScopesBeforeWalkingTheirChildren(): void
    {
        $grammar = new Grammar('root', ['root' => new ProductionRule('root', [new Production([new NonTerminal('root')]), new Production([new Terminal('T')])])]);
        $compiler = new GrammarCompiler($grammar);
        $scope = new Scope();
        self::assertSame($compiler->rule('root', $scope), $compiler->rule('root', $scope));
        $prepared = $compiler->compile('root', []);
        self::assertCount(1, $prepared->grammar->ruleMap);
        self::assertCount(2, $prepared->grammar->ruleMap[$prepared->grammar->startSymbol]->alternatives);
    }

    public function testItemRejectsNullableAndBranchingRecursionForOrderedLists(): void
